// Extract work items from webhook payload
// Expected: {stuck: [], retries: [], orphaned: []}
const payload = $input.first().json.body || $input.first().json;

const stuck = Array.isArray(payload.stuck) ? payload.stuck : [];
const retries = Array.isArray(payload.retries) ? payload.retries : [];
const orphaned = Array.isArray(payload.orphaned) ? payload.orphaned : [];

const counts = {
  stuck: stuck.length,
  retries: retries.length,
  orphaned: orphaned.length
};

const totalWork = counts.stuck + counts.retries + counts.orphaned;

console.log(`[Health Monitor] Received work items: ${counts.stuck} stuck, ${counts.retries} retries, ${counts.orphaned} orphaned (total: ${totalWork})`);

if (totalWork === 0) {
  console.log('[Health Monitor] No work items - workflow will stop (this is expected)');
  return [];
}

return [{
  json: {
    stuck,
    retries,
    orphaned,
    counts,
    totalWork
  }
}];

// Route by work type - separate into parallel streams
const workData = $input.first().json;
const items = [];

// Add stuck orders with _workType marker
for (const order of workData.stuck || []) {
  items.push({
    ...order,
    _workType: 'stuck'
  });
}

// Add retry orders with _workType marker
for (const order of workData.retries || []) {
  items.push({
    ...order,
    _workType: 'retry'
  });
}

// Add orphaned orders with _workType marker
for (const order of workData.orphaned || []) {
  items.push({
    ...order,
    _workType: 'orphaned'
  });
}

console.log(`[Health Monitor] Routed ${items.length} items: ${items.filter(i => i._workType === 'stuck').length} stuck, ${items.filter(i => i._workType === 'retry').length} retry, ${items.filter(i => i._workType === 'orphaned').length} orphaned`);

return items.map(item => ({ json: item }));

// Config for stuck detection
return [{ json: {
  stuckThresholdMinutes: 30,
  maxRetries: 3,
  retryBackoffMultiplier: 2,
  baseRetryDelayMinutes: 5
} }];

// Validate stuck orders from Vercel (double-check threshold)
const config = $('Stuck: Config').first().json;
const inputItems = $input.all();
const orders = [];

// Flatten if needed
for (const item of inputItems) {
  const data = item.json;
  if (Array.isArray(data)) {
    orders.push(...data);
  } else if (data && typeof data === 'object') {
    orders.push(data);
  }
}

const thresholdMs = config.stuckThresholdMinutes * 60 * 1000;
const now = Date.now();
const validatedOrders = [];

for (const order of orders) {
  if (!order.started_at) {
    console.log(`Order ${order.amazon_order_id}: No started_at - skipping`);
    continue;
  }

  const startedAt = new Date(order.started_at).getTime();
  const runningMs = now - startedAt;
  const runningMinutes = Math.floor(runningMs / 1000 / 60);

  if (runningMs > thresholdMs) {
    validatedOrders.push({
      ...order,
      runningMinutes,
      runningMs
    });
  }
}

console.log(`[Stuck Path] Validated ${validatedOrders.length} stuck order(s)`);

if (validatedOrders.length === 0) {
  return [];
}

return validatedOrders.map(order => ({ json: order }));

