// Check if order should be retried or requires manual review
const failedOrder = $input.first().json;
const config = $('Stuck: Config').first().json;
const retryCount = failedOrder.retry_count || 0;
const maxRetries = config.maxRetries;

if (retryCount >= maxRetries) {
  return [{
    json: {
      ...failedOrder,
      action: 'require_manual_review',
      reason: `Max retries (${maxRetries}) reached`
    }
  }];
}

const delayMinutes = config.baseRetryDelayMinutes * Math.pow(config.retryBackoffMultiplier, retryCount);
const nextRetryAt = new Date(Date.now() + delayMinutes * 60 * 1000).toISOString();

return [{
  json: {
    ...failedOrder,
    action: 'schedule_retry',
    nextRetryAt,
    delayMinutes,
    newRetryCount: retryCount + 1,
    order_id: failedOrder.order_id
  }
}];

// Log alert for manual review
const order = $input.first().json;

console.error('[Stuck Path] 🚨 MANUAL REVIEW REQUIRED');
console.error(`[Stuck Path] Order: ${order.amazon_order_id || order.orderId || 'unknown'}`);
console.error(`[Stuck Path] Workflow: ${order.current_workflow || 'unknown'}`);
console.error(`[Stuck Path] Error: ${order.error_message || 'Workflow timeout'}`);
console.error(`[Stuck Path] Retry Count: ${order.retry_count || 0}`);
console.error(`[Stuck Path] Running Minutes: ${order.runningMinutes || 'unknown'}`);

// TODO: Send to Slack/Email/Dashboard

return [{ json: order }];

