// Merge all results from all three paths with detailed logging
// Note: HTTP Request nodes return Supabase responses (no _workType)
// We identify work type by checking which path the item came from
const allItems = $input.all();

console.log(`\n[Merge Node] ========================================`);
console.log(`[Merge Node] Starting merge of ${allItems.length} item(s) from all paths`);
console.log(`[Merge Node] Timestamp: ${new Date().toISOString()}`);

const stuckProcessed = [];
const retriesProcessed = [];
const orphanedProcessed = [];
const unclassified = [];

for (let i = 0; i < allItems.length; i++) {
  const item = allItems[i];
  const data = item.json;
  const orderId = data.amazon_order_id || data.orderId || data.id || 'unknown';

  console.log(`\n[Merge Node] Processing item ${i + 1}/${allItems.length}:`);
  console.log(`  Order ID: ${orderId}`);
  console.log(`  Has _workType: ${!!data._workType} (value: ${data._workType || 'none'})`);
  console.log(`  Has isRetry: ${data.isRetry === true}`);
  console.log(`  Has runningMinutes: ${data.runningMinutes !== undefined} (value: ${data.runningMinutes})`);
  console.log(`  Has error_type: ${!!data.error_type} (value: ${data.error_type || 'none'})`);
  console.log(`  Has orphan_reason: ${!!data.orphan_reason} (value: ${data.orphan_reason || 'none'})`);
  console.log(`  Has action: ${!!data.action} (value: ${data.action || 'none'})`);

  let classified = false;
  let classificationReason = '';

  // Identify work type by data characteristics
  if (data._workType) {
    // Explicit marker (from Prep for Router)
    classificationReason = `Explicit _workType marker: ${data._workType}`;
    if (data._workType === 'stuck') {
      stuckProcessed.push(data);
      classified = true;
    } else if (data._workType === 'retry') {
      retriesProcessed.push(data);
      classified = true;
    } else if (data._workType === 'orphaned') {
      orphanedProcessed.push(data);
      classified = true;
    }
  } else if (data.isRetry === true && data.orderId) {
    // Retry path: Prep for Router output
    classificationReason = 'Retry path: isRetry=true and orderId present';
    retriesProcessed.push(data);
    classified = true;
  } else if (data.runningMinutes !== undefined || data.error_type === 'workflow_timeout') {
    // Stuck path: has runningMinutes or workflow_timeout error
    classificationReason = data.runningMinutes !== undefined 
      ? `Stuck path: runningMinutes=${data.runningMinutes}`
      : `Stuck path: error_type=workflow_timeout`;
    stuckProcessed.push(data);
    classified = true;
  } else if (data.orphan_reason || data.action) {
    // Orphaned path: has orphan classification
    classificationReason = data.orphan_reason 
      ? `Orphaned path: orphan_reason=${data.orphan_reason}`
      : `Orphaned path: action=${data.action}`;
    orphanedProcessed.push(data);
    classified = true;
  } else if (data.amazon_order_id) {
    // Fallback: default to orphaned if we can't determine
    classificationReason = 'Fallback: defaulting to orphaned (has amazon_order_id but no clear markers)';
    orphanedProcessed.push(data);
    classified = true;
  } else {
    classificationReason = 'UNCLASSIFIED: No identifying markers found';
    unclassified.push({ orderId, data });
  }

  console.log(`  Classification: ${classified ? '✅ CLASSIFIED' : '❌ UNCLASSIFIED'}`);
  console.log(`  Reason: ${classificationReason}`);
}

console.log(`\n[Merge Node] Classification Summary:`);
console.log(`  Stuck: ${stuckProcessed.length} item(s)`);
console.log(`  Retries: ${retriesProcessed.length} item(s)`);
console.log(`  Orphaned: ${orphanedProcessed.length} item(s)`);
console.log(`  Unclassified: ${unclassified.length} item(s)`);

if (unclassified.length > 0) {
  console.error(`\n[Merge Node] ⚠️  WARNING: ${unclassified.length} unclassified item(s) found!`);
  for (const unclass of unclassified) {
    console.error(`  - Order ID: ${unclass.orderId}`);
    console.error(`    Data keys: ${Object.keys(unclass.data).join(', ')}`);
  }
}

const summary = {
  timestamp: new Date().toISOString(),
  stuck: {
    count: stuckProcessed.length,
    orders: stuckProcessed.map(o => o.amazon_order_id || o.orderId).filter(Boolean)
  },
  retries: {
    count: retriesProcessed.length,
    orders: retriesProcessed.map(o => o.amazon_order_id || o.orderId).filter(Boolean)
  },
  orphaned: {
    count: orphanedProcessed.length,
    orders: orphanedProcessed.map(o => o.amazon_order_id).filter(Boolean)
  },
  unclassified: {
    count: unclassified.length,
    items: unclassified.map(u => u.orderId)
  },
  total: allItems.length
};

console.log(`\n[Merge Node] Final Summary:`);
console.log(JSON.stringify(summary, null, 2));
console.log(`[Merge Node] ========================================\n`);

return [{ json: summary }];

// Alert: Health Monitor Summary
const summary = $input.first().json;

console.log('\n=== HEALTH MONITOR SUMMARY ===');
console.log(`Timestamp: ${summary.timestamp}`);
console.log(`\nStuck Orders Processed: ${summary.stuck.count}`);
if (summary.stuck.count > 0) {
  console.log(`  Orders: ${summary.stuck.orders.join(', ')}`);
}
console.log(`\nRetry Orders Processed: ${summary.retries.count}`);
if (summary.retries.count > 0) {
  console.log(`  Orders: ${summary.retries.orders.join(', ')}`);
}
console.log(`\nOrphaned Orders Processed: ${summary.orphaned.count}`);
if (summary.orphaned.count > 0) {
  console.log(`  Orders: ${summary.orphaned.orders.join(', ')}`);
}
if (summary.unclassified && summary.unclassified.count > 0) {
  console.error(`\n⚠️  UNCLASSIFIED ITEMS: ${summary.unclassified.count}`);
  console.error(`  Items: ${summary.unclassified.items.join(', ')}`);
  console.error('  This indicates a potential issue with work type identification!');
}
console.log(`\nTotal Items Processed: ${summary.total}`);
console.log('==============================\n');

// TODO: Send to Slack/Email/Dashboard

return [{ json: summary }];
